'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',video:'M15 8l6-4v16l-6-4 M3 6h12v12H3z',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16',play:'M9 5l11 7-11 7z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',card:'M2 5h20v14H2z M2 10h20 M6 15h3',chart:'M4 3v18h18 M9 16v-5 M14 16V7 M19 16V4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M10 2h4l1 3 3 1 3-1 2 4-2 2v3l2 2-2 4-3-1-3 1-1 3h-4l-1-3-3-1-3 1-2-4 2-2v-3L1 9l2-4 3 1 3-1z',help:'M12 17h.01 M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 3 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',chevron:'M9 5l7 7-7 7',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',link:'M10 13a5 5 0 0 0 7 0l4-4a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-4 4a5 5 0 0 0 7 7l2-2',logout:'M9 21H3V3h6 M9 12h13 M17 7l5 5-5 5',menu:'M4 6h16 M4 12h16 M4 18h16',close:'M6 6l12 12 M18 6L6 18',check:'M4 12l5 5L20 6',chat:'M21 15a3 3 0 0 1-3 3H8l-6 4V5a3 3 0 0 1 3-3h13a3 3 0 0 1 3 3z',cloud:'M7 18a6 6 0 1 1 2-11 6 6 0 0 1 11 3 4 4 0 0 1-1 8z',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6z M8 12l3 3 5-5',more:'M5 12h.01 M12 12h.01 M19 12h.01',mic:'M9 3h6v10H9z M5 10v3a7 7 0 0 0 14 0v-3 M12 20v3',mail:'M3 5h18v14H3z M3 5l9 8 9-8',file:'M5 2h9l5 5v15H5z M14 2v6h5 M9 12h6 M9 16h6',refresh:'M20 7V2l-4 4 M4 17v5l4-4 M20 7a8 8 0 0 0-14-3 M4 17a8 8 0 0 0 14 3'};
const icon=(name)=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]||paths.grid}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brand=()=>`<div class="brand"><span class="brandmark">ϟ</span>fastermeet<span class="dot">.</span></div>`;
const initials=v=>String(v).split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase();
const now=new Date(), dateISO=d=>new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10),today=dateISO(now);
const addDays=n=>{const d=new Date(now);d.setDate(d.getDate()+n);return dateISO(d)};
const niceDate=d=>new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
const money=n=>new Intl.NumberFormat('en-EG',{maximumFractionDigits:0}).format(n);
const plans=[{name:'Starter',price:990,capacity:100,storage:10,features:['100 meeting participants','10 GB recording storage','Unlimited meetings','Personal workspace']},{name:'Business',price:2490,capacity:300,storage:100,features:['300 meeting participants','100 GB recording storage','Teams & group chat','Webinars, invoices & reports']},{name:'Enterprise',price:5990,capacity:1000,storage:500,features:['1,000 webinar attendees','500 GB recording storage','Advanced team permissions','Priority support & integrations']}];
const seed=()=>({version:1,profile:{name:'Alex Morgan',email:'alex@example.com',company:'Acme Studio',type:'Business',timezone:'Africa/Cairo',notifications:true,reminders:true},plan:'Business',addons:[],meetings:[{id:'m1',title:'Product design sync',date:today,time:'10:30',duration:45,type:'Meeting',team:'Design team',guests:'sara@example.com,omar@example.com',host:'Zoom master 01',status:'Scheduled',record:true},{id:'m2',title:'Building better remote teams',date:today,time:'14:00',duration:60,type:'Webinar',team:'Everyone',guests:'',host:'Zoom master 02',status:'Scheduled',record:true},{id:'m3',title:'Sprint planning · Q4 launch',date:addDays(1),time:'09:00',duration:30,type:'Meeting',team:'Engineering',guests:'',host:'Zoom master 01',status:'Scheduled',record:false},{id:'m4',title:'Customer onboarding workshop',date:addDays(3),time:'12:00',duration:60,type:'Webinar',team:'Customer success',guests:'',host:'Zoom master 02',status:'Scheduled',record:true},{id:'m5',title:'Weekly team catch-up',date:addDays(-3),time:'11:00',duration:35,type:'Meeting',team:'Everyone',guests:'',host:'Zoom master 01',status:'Completed',record:true}],recordings:[{id:'r1',title:'Weekly team catch-up',date:addDays(-3),duration:'35:12',size:246,team:'Everyone',archive:'S3 archived',retention:90},{id:'r2',title:'Designing with intention',date:addDays(-5),duration:'48:06',size:380,team:'Design team',archive:'Cloud',retention:60},{id:'r3',title:'Product strategy workshop',date:addDays(-7),duration:'1:02:34',size:512,team:'Engineering',archive:'S3 archived',retention:90}],members:[{id:'u1',name:'Alex Morgan',email:'alex@example.com',role:'Owner',team:'Everyone',status:'Active'},{id:'u2',name:'Sara Hassan',email:'sara@example.com',role:'Admin',team:'Design team',status:'Active'},{id:'u3',name:'Omar Ali',email:'omar@example.com',role:'Member',team:'Engineering',status:'Active'},{id:'u4',name:'Maya Williams',email:'maya@example.com',role:'Member',team:'Customer success',status:'Active'}],customers:[{id:'c1',name:'Acme Studio',email:'alex@example.com',plan:'Business',status:'Active'},{id:'c2',name:'Horizon Academy',email:'demo@horizon.example',plan:'Enterprise',status:'Active'},{id:'c3',name:'Nile Creative',email:'demo@nile.example',plan:'Starter',status:'Pending'}],invoices:[{id:'FM-2026-1022',date:today,description:'Business plan · Monthly subscription',amount:2490,status:'Paid'},{id:'FM-2026-0922',date:addDays(-30),description:'Business plan · Monthly subscription',amount:2490,status:'Paid'}],messages:[{id:1,name:'Sara Hassan',channel:'general',text:'The new workshop agenda is ready. Looking forward to our next session!',time:'09:42'},{id:2,name:'Omar Ali',channel:'general',text:'Great! I have added the demo notes to the sprint planning meeting.',time:'09:45'},{id:3,name:'Maya Williams',channel:'design',text:'Let’s review the onboarding flow in today’s design sync.',time:'09:52'}],integrations:{Zoom:true,'Amazon S3':true,Vimeo:false,Moodle:true,'Payment gateway':true},hosts:[{name:'Zoom master 01',email:'host01@example.com',capacity:300,status:'Available'},{name:'Zoom master 02',email:'host02@example.com',capacity:1000,status:'Available'}],moodle:[{course:'Remote collaboration essentials',session:'Building better remote teams',date:today}],activity:[{text:'Your Business subscription was renewed',time:'1 hour ago'},{text:'Weekly team catch-up recording is ready',time:'3 hours ago'},{text:'Sara joined the Design team',time:'Yesterday'}],notificationsRead:false});
let db;try{db=JSON.parse(localStorage.getItem('fastermeet-demo-v1'))||seed();if(db.version!==1)db=seed()}catch{db=seed()}
let session;try{session=JSON.parse(sessionStorage.getItem('fm-session'))}catch{session=null}
const initialInvite=decodeURIComponent(location.hash);
let page=(decodeURIComponent(location.hash.slice(1))||'Overview'),authMode='login',loginRole='customer',meetingFilter='Upcoming',searchText='',channel='general',reportType='Meetings',calMonth=now.getMonth(),calYear=now.getFullYear(),selectedDay=null,mobileOpen=false;
const save=()=>localStorage.setItem('fastermeet-demo-v1',JSON.stringify(db));
const log=text=>{db.activity.unshift({text,time:'Just now'});db.activity=db.activity.slice(0,10);save()};
const isAdmin=()=>session?.role==='admin';
const uid=p=>p+Date.now().toString(36)+Math.random().toString(36).slice(2,6);
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
const btn=(text,action,cls='',id='')=>`<button class="${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${text}</button>`;
const badge=(s,cls='')=>`<span class="badge ${cls||(/Cancelled|Failed/.test(s)?'red':/Pending|Invited/.test(s)?'orange':/Completed/.test(s)?'gray':'')}">${esc(s)}</span>`;
const navs=()=>isAdmin()?[['Overview','grid'],['Meetings','video'],['Calendar','calendar'],['Recordings','play'],['Customers','users'],['Team space','users'],['Subscriptions','card'],['Reports','chart'],['Integrations','cloud'],['Settings','settings']]:[['Overview','grid'],['Meetings','video'],['Calendar','calendar'],['Recordings','play'],['Team space','users'],['Subscription','card'],['Reports','chart'],['Integrations','cloud'],['Settings','settings']];
function go(p){if(!session)return;if(!navs().some(n=>n[0]===p))p='Overview';page=p;location.hash=p;searchText='';selectedDay=null;mobileOpen=false;render();window.scrollTo(0,0)}
window.addEventListener('hashchange',()=>{const p=decodeURIComponent(location.hash.slice(1));if(session&&p!==page)go(p)});
function metric(label,value,sub,ic='video'){return `<div class="metric"><div class="metric-top">${label}<span class="metric-icon">${icon(ic)}</span></div><strong>${value}</strong><small>${sub}</small></div>`}
function head(title,desc,actions=''){return `<div class="pagehead"><div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function login(){const registering=authMode==='register',reset=authMode==='reset';return `<div class="login-shell"><aside class="login-story">${brand()}<h1>Good conversations.<br><span>Great possibilities.</span></h1><p>One thoughtful space to meet, collaborate, and bring your next big idea to life.</p><div class="story-card"><p>From the first hello to the final breakthrough. Bring your people together, wherever work takes you.</p><div class="story-person"><span class="avatar green">FM</span><div>Your team's next chapter<small>Starts with a conversation</small></div></div></div><div class="orbit-large"></div><div class="login-credit">CRAFTED BY ALLAM SOLUTIONS · FASTER MEET</div></aside><main class="login-form"><div class="login-inner"><div class="eyebrow" style="color:#7d976d">LET’S CONNECT</div><h2>${registering?'Create your workspace':reset?'A fresh start':'Welcome back.'}</h2><p>${registering?'Make room for better collaboration.':reset?'Try the password recovery experience.':'Your people, your meetings, your next big thing.'}</p>${!reset&&!registering?`<div class="login-mode">${btn('Customer workspace','login-role',loginRole==='customer'?'active':'','customer')}${btn('Admin console','login-role',loginRole==='admin'?'active':'','admin')}</div>`:''}<form id="auth-form" data-form="auth">${registering?`<div class="form-field"><label for="auth-name">Full name</label><input id="auth-name" name="name" required maxlength="80" placeholder="Your full name" autocomplete="name"></div>`:''}<div class="form-field"><label for="auth-email">Email address</label><input id="auth-email" name="email" type="email" required placeholder="you@company.com" autocomplete="email"></div>${!reset?`<div class="form-field"><label for="auth-password">Password</label><input id="auth-password" name="password" type="password" required minlength="8" placeholder="Enter your password" autocomplete="${registering?'new-password':'current-password'}"></div>`:''}${registering?`<div class="form-field"><label for="auth-type">Account type</label><select id="auth-type" name="type"><option>Business</option><option>Individual</option></select></div>`:!reset?`<div class="row tiny"><span class="muted">Interactive demonstration</span>${btn('Forgot password?','auth-mode','ghost small','reset')}</div>`:''}<div id="auth-error" class="form-error" role="alert"></div><button type="submit">${registering?'Create demo workspace':reset?'Preview recovery email':'Sign in to workspace'} ${icon('arrow')}</button></form><div class="auth-footer">${reset||registering?btn('Back to sign in','auth-mode','','login'):`New to Faster Meet? ${btn('Create an account','auth-mode','','register')}`}</div>${!reset&&!registering?`<div class="demo-box"><strong>Take a look around</strong><br><span>Explore with sample data. No real account needed.</span>${btn('Enter '+(loginRole==='admin'?'admin':'customer')+' demo '+icon('arrow'),'demo-login','')}</div>`:''}<p class="tiny" style="margin-top:22px;margin-bottom:0;text-align:center">Client preview · External services are simulated.</p></div></main></div>`}
function render(){if(!session){$('#app').innerHTML=login();return}if(!navs().some(n=>n[0]===page))page='Overview';const user=isAdmin()?'Platform admin':db.profile.name;$('#app').innerHTML=`<div class="shell"><aside class="sidebar ${mobileOpen?'open':''}">${brand()}<div class="workspace"><span class="avatar green">${isAdmin()?'AS':initials(db.profile.company||db.profile.name)}</span><div><b>${esc(isAdmin()?'Allam Solutions':db.profile.company||'My workspace')}</b><small>${isAdmin()?'Platform administration':esc(db.profile.type)+' workspace'}</small></div></div><div class="nav-label">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${navs().map(([n,i])=>btn(icon(i)+n+(n==='Meetings'?`<span class="count">${db.meetings.filter(m=>m.status==='Scheduled').length}</span>`:''),'navigate',page===n?'active':'',n)).join('')}</nav><div class="sidebar-foot"><div class="upgrade"><b>${isAdmin()?'Everything in one place':db.plan+' plan'}</b><div>${isAdmin()?'Keep your platform running smoothly.':'More possibilities. Less friction.'}</div>${btn(isAdmin()?'Platform settings':'Explore plans '+icon('arrow'),'navigate','small',isAdmin()?'Settings':'Subscription')}</div><div class="nav">${btn(icon('help')+'Help & demo guide','help')}${btn(icon('logout')+'Sign out','logout')}</div><div class="credit">BY ALLAM SOLUTIONS</div></div></aside><main class="main"><header class="topbar">${btn(icon('menu'),'mobile-menu','iconbtn mobile-menu')}<div class="breadcrumb">Workspace <span style="padding:0 9px">/</span><strong>${esc(page)}</strong></div><span class="demo-tag">INTERACTIVE PREVIEW</span><div class="search">${icon('search')}<input aria-label="Search meetings" id="global-search" placeholder="Search meetings…"></div>${btn(icon('bell'),'notifications','iconbtn')}<div class="topuser"><span class="avatar green">${initials(user)}</span><span class="usertext">${esc(user)}<small>${isAdmin()?'Administrator':esc(db.plan)+' member'}</small></span></div></header><div class="content">${renderPage()}<footer class="footer"><span>© ${now.getFullYear()} Faster Meet. Thoughtfully connected.</span><span>Designed & developed by Allam Solutions</span></footer></div></main></div>`}
function renderPage(){return ({Overview:overview,Meetings:meetingsPage,Calendar:calendarPage,Recordings:recordingsPage,'Team space':teamPage,Subscription:subscriptionPage,Subscriptions:adminSubscriptions,Customers:customersPage,Reports:reportsPage,Integrations:integrationsPage,Settings:settingsPage}[page]||overview)()}
function upcoming(){return db.meetings.filter(m=>m.status==='Scheduled').sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))}
function meetingRow(m){const d=new Date(m.date+'T12:00:00');return `<div class="meeting"><div class="datebox"><small>${d.toLocaleDateString('en',{month:'short'})}</small><b>${d.getDate()}</b></div><div class="meeting-body"><h3>${esc(m.title)}</h3><div class="meeting-meta"><span>${icon('clock').replace('class="icon"','class="icon" style="width:11px;height:11px;vertical-align:middle"')} ${esc(m.time)} · ${m.duration} min</span><span>${esc(m.team)}</span>${badge(m.type,m.type==='Webinar'?'purple':'')}</div></div><div class="actions">${m.status==='Scheduled'?btn('Join '+icon('arrow'),'join','small',m.id):badge(m.status)}${btn(icon('more'),'meeting-detail','ghost',m.id)}</div></div>`}
function miniCalendar(){const first=new Date(calYear,calMonth,1).getDay(),days=new Date(calYear,calMonth+1,0).getDate();return `<div class="panel"><div class="calendar-head"><span>${new Date(calYear,calMonth).toLocaleDateString('en',{month:'long',year:'numeric'})}</span><div>${btn('‹','month-prev','ghost small')}${btn('›','month-next','ghost small')}</div></div><div class="calendar-grid">${['S','M','T','W','T','F','S'].map(x=>`<span>${x}</span>`).join('')}${'<span></span>'.repeat(first)}${Array.from({length:days},(_,i)=>{const d=`${calYear}-${String(calMonth+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;return btn(i+1,'day',(d===today?'current ':'')+(db.meetings.some(m=>m.date===d)?'has-event':''),d)}).join('')}</div><div class="cal-note"><span class="dot-small"></span>${upcoming().filter(m=>m.date===today).length} meetings scheduled today</div></div>`}
function overview(){let list=upcoming();return head(isAdmin()?'A clearer view of your platform.':`Good ${now.getHours()<12?'morning':'afternoon'}, ${esc(db.profile.name.split(' ')[0])} <span style="font-weight:400">✳</span>`,isAdmin()?'Monitor your customers, meetings, and platform activity.':'Here’s what’s happening in your workspace today.',btn(icon('plus')+'Schedule meeting','schedule'))+`<section class="hero"><div><div class="eyebrow">MAKE EVERY CONVERSATION COUNT</div><h2>A little more connection.<br>A lot more possibility.</h2><p>Your next great idea is just a conversation away.</p>${btn(icon('video')+'Start instant meeting','instant','lime small')}${btn('Join with a link '+icon('arrow'),'join-link','hero-link small','')}</div><div class="hero-art"><div class="orbit"></div><div class="orbit"></div><div class="orbit"></div><div class="floating-tile">${icon('video')}</div><span class="avatar a1 yellow">SH</span><span class="avatar a2">OA</span></div></section><div class="metrics">${metric(isAdmin()?'Active customers':'Upcoming meetings',isAdmin()?db.customers.filter(c=>c.status==='Active').length:list.length,'<span class="positive">↗ Ready for what’s next</span>','video')}${metric(isAdmin()?'Subscription revenue':'Meeting time',isAdmin()?'EGP '+money(db.invoices.reduce((s,x)=>s+x.amount,0)):db.meetings.filter(x=>x.status==='Completed').reduce((s,x)=>s+x.duration,0)+' min','This demo workspace','clock')}${metric('Team members',db.members.length,'Working better, together','users')}${metric('Cloud recordings',db.recordings.length,money(db.recordings.reduce((s,r)=>s+r.size,0))+' MB safely stored','cloud')}</div><div class="dashboard-grid"><div class="stack"><section class="panel"><div class="panel-head"><h2>Coming up next</h2>${btn('View all meetings '+icon('arrow'),'navigate','ghost','Meetings')}</div><div class="tabs">${btn('Upcoming','overview-tab','active','Upcoming')}${btn('Completed','overview-tab','','Completed')}</div><div id="overview-meetings">${list.slice(0,3).map(meetingRow).join('')||'<div class="empty">Your calendar is clear. Make room for a conversation.</div>'}</div></section><section class="panel"><div class="panel-head"><h2>Recent recordings</h2>${btn('View library '+icon('arrow'),'navigate','ghost','Recordings')}</div><div class="recording-grid">${db.recordings.slice(0,3).map(recordingCard).join('')}</div></section></div><div class="stack">${miniCalendar()}<section class="panel"><div class="panel-head"><h2>Workspace activity</h2>${icon('more')}</div>${db.activity.slice(0,3).map(a=>`<div class="activity"><span class="point"></span><div>${esc(a.text)}<small>${esc(a.time)}</small></div></div>`).join('')}<div class="usage"><div class="row"><b>Recording storage</b><span>${(db.recordings.reduce((s,r)=>s+r.size,0)/1024).toFixed(1)} / ${plans.find(p=>p.name===db.plan).storage} GB</span></div><div class="progress"><i style="width:${Math.min(100,db.recordings.reduce((s,r)=>s+r.size,0)/1024/plans.find(p=>p.name===db.plan).storage*100)}%"></i></div><span class="muted">Room for your best conversations.</span></div></section></div></div>`}
function meetingsPage(){let list=db.meetings.filter(m=>(meetingFilter==='All'||(meetingFilter==='Upcoming'?m.status==='Scheduled':m.status===meetingFilter))&&(!selectedDay||m.date===selectedDay)&&`${m.title} ${m.team} ${m.type}`.toLowerCase().includes(searchText.toLowerCase())).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return head('Your next great conversation.','Plan it, share it, and bring everyone together.',btn('Join with a link','join-link','secondary')+btn(icon('plus')+'Schedule meeting','schedule'))+`<section class="panel"><div class="toolbar"><div class="tabs" style="margin:0">${['Upcoming','Completed','Cancelled','All'].map(n=>btn(n,'meeting-filter',meetingFilter===n?'active':'',n)).join('')}</div><input class="field-search" id="meeting-search" aria-label="Filter meetings" placeholder="Search by title or team…" value="${esc(searchText)}"></div>${selectedDay?`<div class="notice">Showing ${niceDate(selectedDay)} ${btn('Clear','clear-day','ghost small')}</div>`:''}<div id="meeting-list">${list.map(meetingRow).join('')||'<div class="empty">No meetings match this view.</div>'}</div></section>`}
function calendarPage(){const first=new Date(calYear,calMonth,1).getDay(),days=new Date(calYear,calMonth+1,0).getDate();return head('Make space for what matters.','Your meetings and webinars, all in one place.',btn(icon('plus')+'New event','schedule'))+`<section class="panel"><div class="panel-head"><h2>${new Date(calYear,calMonth).toLocaleDateString('en',{month:'long',year:'numeric'})}</h2><div class="actions">${btn('‹','month-prev','secondary small')}${btn('Today','month-today','secondary small')}${btn('›','month-next','secondary small')}</div></div><div class="full-cal">${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map(d=>`<div class="cal-label">${d.slice(0,3)}</div>`).join('')}${'<div class="day"></div>'.repeat(first)}${Array.from({length:days},(_,i)=>{const d=`${calYear}-${String(calMonth+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;return `<div class="day ${d===today?'today':''}"><span>${i+1}</span>${db.meetings.filter(m=>m.date===d&&m.status!=='Cancelled').map(m=>btn(esc(m.time)+' '+esc(m.title),'meeting-detail','',m.id)).join('')}${btn('+','schedule-day','ghost small',d)}</div>`}).join('')}</div></section>`}
function recordingCard(r,i=0){return `<article class="recording"><div class="recording-preview ${i%3===1?'purple':i%3===2?'peach':''}">${btn(icon('play'),'play','',r.id)}<span class="duration">${esc(r.duration)}</span></div><div class="recording-info"><h3>${esc(r.title)}</h3><div class="tiny muted">${niceDate(r.date)} · ${r.size} MB</div><div class="row">${badge(r.archive,'gray')}<div>${btn(icon('link'),'share-recording','ghost small',r.id)}${btn(icon('download'),'download-recording','ghost small',r.id)}</div></div></div></article>`}
function recordingsPage(){const list=db.recordings.filter(r=>r.title.toLowerCase().includes(searchText.toLowerCase()));return head('Keep the conversation going.','Revisit the ideas, breakthroughs, and moments worth keeping.',btn(icon('cloud')+'Archive settings','archive-settings','secondary'))+`<div class="notice">Your recording library · Playback and downloads use a locally generated sample. Zoom, S3, and Vimeo connections are simulated in this preview.</div><div class="toolbar"><input id="recording-search" class="field-search" aria-label="Search recordings" placeholder="Find a recording…" value="${esc(searchText)}"><span class="tiny muted">${list.length} recordings · ${(list.reduce((s,r)=>s+r.size,0)/1024).toFixed(1)} GB</span></div><div class="recording-grid">${list.map(recordingCard).join('')||'<div class="empty">No recordings found.</div>'}</div>`}
function teamPage(){return head('Better, together.','A shared space for your people and their best ideas.',btn(icon('plus')+'Invite teammate','invite'))+`<section class="panel"><div class="panel-head"><h2>Your team</h2><span class="tiny muted">${db.members.length} members</span></div><div class="table-wrap"><table><thead><tr><th>Member</th><th>Team</th><th>Role</th><th>Status</th><th>Manage</th></tr></thead><tbody>${db.members.map(m=>`<tr><td><div class="actions"><span class="avatar ${m.id==='u2'?'yellow':'green'}">${initials(m.name)}</span><div><b>${esc(m.name)}</b><small>${esc(m.email)}</small></div></div></td><td>${esc(m.team)}</td><td>${esc(m.role)}</td><td>${badge(m.status)}</td><td>${m.role==='Owner'?'<span class="tiny muted">Workspace owner</span>':btn('Edit','member-edit','secondary small',m.id)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel chat section-space"><aside class="channels"><h3>Channels</h3>${['general','design','engineering'].map(c=>btn('# '+c,'channel',channel===c?'active':'',c)).join('')}</aside><div class="messages-area"><div class="chat-head"><h3># ${esc(channel)}</h3><span class="tiny muted">A place for the team to stay connected.</span></div><div class="messages" id="messages">${db.messages.filter(m=>m.channel===channel).map(m=>`<div class="message"><span class="avatar green">${initials(m.name)}</span><div><b>${esc(m.name)}</b><small>${esc(m.time)}</small><p>${esc(m.text)}</p></div></div>`).join('')||'<div class="empty">Start a new conversation.</div>'}</div><form class="composer" data-form="chat"><input name="message" required maxlength="1500" aria-label="Message channel" placeholder="Write to #${esc(channel)}…"><button type="submit">Send ${icon('arrow')}</button></form></div></section>`}
function subscriptionPage(){const current=plans.find(p=>p.name===db.plan);return head('The right space to grow.','Flexible plans for every kind of connection.',badge('Current plan: '+db.plan))+`<div class="notice"><div class="row"><div><b>${esc(db.plan)} subscription is active.</b> Next renewal: ${niceDate(addDays(30))}. ${db.addons.length?'Add-ons: '+db.addons.map(esc).join(', '):''}</div>${btn('Manage renewal','renewal','secondary small')}</div></div><div class="plan-grid">${plans.map(p=>`<section class="plan ${p.name==='Business'?'featured':''}">${p.name==='Business'?'<span class="plan-tag">MOST POPULAR</span>':''}<h2>${p.name}</h2><p class="tiny muted">${p.name==='Starter'?'For your everyday conversations.':p.name==='Business'?'For teams doing great things.':'For connections at every scale.'}</p><div class="price">${money(p.price)} <small>EGP / month</small></div><ul>${p.features.map(f=>`<li>${f}</li>`).join('')}</ul>${btn(db.plan===p.name?'Current plan':'Choose '+p.name,db.plan===p.name?'current-plan':'checkout',db.plan===p.name?'secondary':'',p.name)}</section>`).join('')}</div><section class="panel section-space"><div class="panel-head"><h2>A little extra, when you need it.</h2></div><div class="two-col"><div class="status-item"><div><b>Extra cloud storage</b><small class="muted" style="display:block;margin-top:5px">+100 GB · EGP 350 / month</small></div>${btn(db.addons.includes('100 GB storage')?'Added':'Add storage','addon','secondary small','100 GB storage')}</div><div class="status-item"><div><b>Webinar capacity</b><small class="muted" style="display:block;margin-top:5px">+500 attendees · EGP 750 / month</small></div>${btn(db.addons.includes('500 webinar attendees')?'Added':'Add capacity','addon','secondary small','500 webinar attendees')}</div></div></section>${invoiceTable()}`}
function invoiceTable(){return `<section class="panel section-space"><div class="panel-head"><h2>Billing history</h2>${btn(icon('download')+'Export invoices','export-invoices','secondary small')}</div><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Description</th><th>Date</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>${db.invoices.map(x=>`<tr><td><b>${esc(x.id)}</b></td><td>${esc(x.description)}</td><td>${niceDate(x.date)}</td><td>EGP ${money(x.amount)}</td><td>${badge(x.status)}</td><td>${btn(icon('file')+'View PDF','invoice','secondary small',x.id)}</td></tr>`).join('')}</tbody></table></div></section>`}
function adminSubscriptions(){return head('Subscriptions, in focus.','Manage plans, payment status, and customer subscriptions.',btn('Manage plan catalog','plan-catalog','secondary'))+`<div class="metrics">${metric('Active subscriptions',db.customers.filter(c=>c.status==='Active').length,'Across all customers','card')}${metric('Demo receipts','EGP '+money(db.invoices.filter(i=>i.status==='Paid').reduce((s,x)=>s+x.amount,0)),'From sample invoices','chart')}${metric('Pending requests',db.customers.filter(c=>c.status==='Pending').length,'Ready for review','clock')}${metric('Available plans',3,'Starter · Business · Enterprise','grid')}</div><section class="panel"><h2>Customer subscriptions</h2><div class="table-wrap section-space"><table><thead><tr><th>Customer</th><th>Plan</th><th>Monthly price</th><th>Status</th><th>Action</th></tr></thead><tbody>${db.customers.map(c=>`<tr><td>${esc(c.name)}<small>${esc(c.email)}</small></td><td>${esc(c.plan)}</td><td>EGP ${money(plans.find(p=>p.name===c.plan).price)}</td><td>${badge(c.status)}</td><td>${btn('Manage','customer-edit','secondary small',c.id)}</td></tr>`).join('')}</tbody></table></div></section>${invoiceTable()}`}
function customersPage(){return head('People behind the platform.','A clear view of every customer and their workspace.',btn(icon('plus')+'Add customer','add-customer'))+`<section class="panel"><div class="toolbar"><h2>All customers</h2><input id="customer-search" aria-label="Search customers" class="field-search" placeholder="Search customers…" value="${esc(searchText)}"></div><div class="table-wrap"><table><thead><tr><th>Workspace</th><th>Contact</th><th>Plan</th><th>Status</th><th></th></tr></thead><tbody>${db.customers.filter(c=>`${c.name} ${c.email}`.toLowerCase().includes(searchText.toLowerCase())).map(c=>`<tr><td><b>${esc(c.name)}</b></td><td>${esc(c.email)}</td><td>${esc(c.plan)}</td><td>${badge(c.status)}</td><td>${btn('Manage customer','customer-edit','secondary small',c.id)}</td></tr>`).join('')}</tbody></table></div></section>`}
const reportNames=['Subscriptions','Revenue','Meetings','Recordings','Customers','Teams'];
function getReport(type){switch(type){case'Subscriptions':return{headers:['Customer','Plan','Status','Monthly EGP'],rows:db.customers.map(c=>[c.name,c.plan,c.status,plans.find(p=>p.name===c.plan).price])};case'Revenue':return{headers:['Invoice','Date','Description','Amount EGP','Status'],rows:db.invoices.map(i=>[i.id,i.date,i.description,i.amount,i.status])};case'Recordings':return{headers:['Title','Date','Duration','Size MB','Archive'],rows:db.recordings.map(r=>[r.title,r.date,r.duration,r.size,r.archive])};case'Customers':return{headers:['Customer','Email','Plan','Status'],rows:db.customers.map(c=>[c.name,c.email,c.plan,c.status])};case'Teams':return{headers:['Member','Email','Team','Role','Status'],rows:db.members.map(m=>[m.name,m.email,m.team,m.role,m.status])};default:return{headers:['Title','Date','Type','Duration min','Host','Status'],rows:db.meetings.map(m=>[m.title,m.date,m.type,m.duration,m.host,m.status])}}}
function reportsPage(){const report=getReport(reportType);const data=Array.from({length:7},(_,i)=>db.meetings.filter(m=>m.date===addDays(i-3)).length);const max=Math.max(...data,1);return head('Turn activity into perspective.','Six report views. One clearer picture of your platform.',btn(icon('download')+'Export CSV','report-export'))+`<div class="two-col"><section class="panel"><div class="panel-head"><h2>Meetings this week</h2>${badge(db.meetings.length+' total','gray')}</div><div class="chart">${data.map((n,i)=>`<div class="chart-col" style="--h:${Math.max(3,n/max*85)}%"><div class="chart-bar" style="height:${Math.max(3,n/max*85)}%"></div><b>${n}</b><small>${new Date(addDays(i-3)+'T12:00:00').toLocaleDateString('en',{weekday:'short'})}</small></div>`).join('')}</div></section><section class="panel"><h2>At a glance</h2><div class="status-item section-space"><span>Recorded conversations</span><b>${db.recordings.length}</b></div><div class="status-item"><span>Total scheduled minutes</span><b>${db.meetings.reduce((s,m)=>s+m.duration,0)}</b></div><div class="status-item"><span>Active teams</span><b>${new Set(db.members.map(m=>m.team)).size}</b></div></section></div><section class="panel section-space"><div class="toolbar"><div><label for="report-type">REPORT VIEW</label><select id="report-type">${reportNames.map(n=>`<option ${n===reportType?'selected':''}>${n}</option>`).join('')}</select></div><span class="tiny muted">${report.rows.length} records · Demo workspace data</span></div><div class="table-wrap"><table><thead><tr>${report.headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${report.rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`}
function integrationsPage(){return head('Your tools, thoughtfully connected.','Bring meetings, learning, payments, and storage into one flow.')+`<div class="notice">Demo connections show the intended experience. No credentials are collected and no requests are sent to these services.</div><div class="two-col"><div>${[['Zoom','Z','Meetings, webinars, host allocation and webhooks.'],['Amazon S3','S3','Cloud archive, retention and recording backups.'],['Vimeo','V','A simple home for video playback.']].map(integrationCard).join('')}</div><div>${[['Moodle','m','Connect courses to scheduled learning sessions.'],['Payment gateway','↗','Hosted checkout, payment status and invoices.']].map(integrationCard).join('')}<section class="panel"><h3>Webhook event log</h3><div class="status-item section-space"><span>meeting.ended</span>${badge('Processed')}</div><div class="status-item"><span>recording.completed</span>${badge('Processed')}</div>${btn('Simulate webhook event','webhook','secondary small')}</section></div></div><section class="panel section-space"><div class="panel-head"><h2>Zoom master accounts</h2>${btn('Add demo host','add-host','secondary small')}</div><div class="table-wrap"><table><thead><tr><th>Account</th><th>Email</th><th>Capacity</th><th>Status</th></tr></thead><tbody>${db.hosts.map(h=>`<tr><td>${esc(h.name)}</td><td>${esc(h.email)}</td><td>${h.capacity} participants</td><td>${badge(h.status)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel section-space"><div class="panel-head"><h2>Moodle course sessions</h2>${btn('Map a course','map-course','secondary small')}</div>${db.moodle.map(x=>`<div class="status-item"><div><b>${esc(x.course)}</b><small class="muted" style="display:block;margin-top:6px">${esc(x.session)} · ${niceDate(x.date)}</small></div>${badge('Linked')}</div>`).join('')}</section>`}
function integrationCard([name,logo,desc]){return `<section class="integration"><div class="service-logo">${logo}</div><div class="detail"><h3>${name}</h3><p>${desc}</p>${badge(db.integrations[name]?'Demo connected':'Disconnected',db.integrations[name]?'':'gray')}</div>${btn('Configure','integration-config','secondary small',name)}</section>`}
function settingsPage(){return head(isAdmin()?'A well-run workspace.':'Make yourself at home.','Manage your profile, preferences, and workspace settings.')+`<div class="settings-grid"><form class="panel" data-form="profile"><div class="panel-head"><h2>Profile & workspace</h2><span class="avatar green">${initials(db.profile.name)}</span></div><div class="fields"><div class="form-field"><label for="p-name">Full name</label><input id="p-name" name="name" required maxlength="80" value="${esc(db.profile.name)}"></div><div class="form-field"><label for="p-email">Email</label><input id="p-email" name="email" type="email" required value="${esc(db.profile.email)}"></div></div><div class="form-field"><label for="p-company">Workspace name</label><input id="p-company" name="company" required maxlength="80" value="${esc(db.profile.company)}"></div><div class="fields"><div class="form-field"><label for="p-type">Account type</label><select id="p-type" name="type">${['Business','Individual'].map(t=>`<option ${db.profile.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="form-field"><label for="p-tz">Timezone</label><select id="p-tz" name="timezone">${['Africa/Cairo','Europe/London','Asia/Dubai','America/New_York'].map(t=>`<option ${db.profile.timezone===t?'selected':''}>${t}</option>`).join('')}</select></div></div><p class="tiny muted">Meeting times are shown in the selected workspace timezone.</p><button type="submit">Save changes ${icon('check')}</button></form><div class="stack"><section class="panel"><h2>Notifications</h2><label class="check-row">Email updates<input type="checkbox" data-setting="notifications" ${db.profile.notifications?'checked':''}></label><label class="check-row">Meeting reminders<input type="checkbox" data-setting="reminders" ${db.profile.reminders?'checked':''}></label></section><section class="panel"><h2>Demo controls</h2><p class="tiny muted">Switch between customer and administrator journeys. Sample data is saved in this browser.</p>${btn('Switch to '+(isAdmin()?'customer':'admin'),'switch-role','secondary')}<div style="margin-top:13px">${btn('Reset sample data','reset-confirm','danger small')}</div></section><section class="panel"><h3>Security & roles</h3><p class="tiny muted">${isAdmin()?'Administrators manage customer accounts, subscription status and integrations.':'Owners manage the workspace. Admins organize teams and sessions. Members join meetings and collaborate.'} This prototype does not provide production security.</p></section></div></div>`}
function modal(title,body,foot='',wide=false){$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2>${btn(icon('close'),'close','ghost')}</div>${body}${foot?`<div class="modal-foot">${foot}</div>`:''}</section></div>`;setTimeout(()=>$('.modal input,.modal select,.modal button')?.focus(),20)}
function closeModal(){$('#modal-root').innerHTML=''}
function formModal(title,form,body,submit='Save changes',extra=''){modal(title,`<form data-form="${form}">${body}<div class="modal-foot">${extra}${btn('Cancel','close','secondary')}<button type="submit">${submit}</button></div></form>`)}
function inputField(label,name,value='',type='text',required=true,extra=''){const id='f-'+name;return `<div class="form-field"><label for="${id}">${label}</label><input id="${id}" type="${type}" name="${name}" value="${esc(value)}" ${required?'required':''} ${extra}></div>`}
function selectField(label,name,options,selected){return `<div class="form-field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(x=>`<option ${x===selected?'selected':''}>${esc(x)}</option>`).join('')}</select></div>`}
function schedule(day=today,id=''){const m=db.meetings.find(m=>m.id===id);formModal(m?'Edit meeting':'Make room for a conversation','schedule',`<input type="hidden" name="id" value="${esc(id)}">${inputField('Meeting title','title',m?.title||'','text',true,'maxlength="120" placeholder="What are we getting together for?"')}<div class="fields">${selectField('Event type','type',['Meeting','Webinar','Fixed meeting'],m?.type||'Meeting')}${selectField('Team','team',['Everyone','Design team','Engineering','Customer success'],m?.team||'Everyone')}</div><div class="fields">${inputField('Date','date',m?.date||day,'date')}${inputField('Time · '+db.profile.timezone,'time',m?.time||'11:00','time')}</div><div class="fields">${inputField('Duration (minutes)','duration',m?.duration||45,'number',true,'min="15" max="480" step="15"')}${selectField('Preferred host','host',['Auto-allocate',...db.hosts.map(h=>h.name)],m?.host||'Auto-allocate')}</div>${inputField('Guests / cohosts (comma-separated emails)','guests',m?.guests||'','text',false,'maxlength="500" placeholder="sara@example.com, omar@example.com"')}<label class="check"><input type="checkbox" name="record" ${m?.record===false?'':'checked'}>Automatically record the session</label><div id="schedule-error" class="form-error" role="alert"></div><p>Hosts are allocated around scheduling conflicts. Invitations and Zoom links are simulated in this client preview.</p>`,m?'Update meeting':'Create meeting')}
function detail(id){const m=db.meetings.find(x=>x.id===id);if(!m)return;modal(m.title,`<div class="row">${badge(m.type,m.type==='Webinar'?'purple':'')}${badge(m.status)}</div><div class="status-item section-space"><span>Date & time</span><b>${niceDate(m.date)} · ${esc(m.time)}</b></div><div class="status-item"><span>Workspace timezone</span><b>${esc(db.profile.timezone)}</b></div><div class="status-item"><span>Duration</span><b>${m.duration} minutes</b></div><div class="status-item"><span>Team</span><b>${esc(m.team)}</b></div><div class="status-item"><span>Host account</span><b>${esc(m.host)}</b></div><div class="status-item"><span>Recording</span><b>${m.record?'Enabled':'Off'}</b></div><p>Guests / cohosts: ${esc(m.guests||'No guests added')}</p><div class="actions">${btn(icon('link')+'Share invite','share-meeting','secondary',id)}${btn(icon('calendar')+'Calendar file','ics','secondary',id)}</div>`,m.status==='Scheduled'?btn('Cancel meeting','cancel-meeting','danger',id)+btn('Edit','edit-meeting','secondary',id)+btn('Join session','join','',id):(m.status==='Cancelled'?btn('Restore meeting','edit-meeting','secondary',id):'')+btn('Close','close','secondary'))}
function share(title,value){modal(title,`<p>Copy this demo link to show the join experience in the same browser.</p><input readonly aria-label="Share link" value="${esc(value)}" id="share-value"><p>Demo records are stored per browser; this link does not synchronize meetings across devices.</p>`,btn('Copy link','copy-link')+btn('Done','close','secondary'))}
function linkFor(id){return location.href.split('#')[0]+'#join/'+id}
function join(id){const m=db.meetings.find(x=>x.id===id);if(!m){toast('That meeting is not in this browser’s demo workspace.');return}if(m.status==='Cancelled'){toast('This meeting has been cancelled.');return}modal('You’re almost there.',`<div class="notice">Session preview · No live audio or video is transmitted.</div><div class="participant" style="background:#eef4e9;color:#274c38"><span class="avatar green">${initials(db.profile.name)}</span><small style="color:#66806a">Camera preview is off</small></div><h3 class="section-space">${esc(m.title)}</h3><p>${esc(m.team)} · ${m.duration} min · ${esc(m.host)}</p><div class="actions">${btn(icon('mic')+'Microphone off','toggle-device','secondary','mic')}${btn(icon('video')+'Camera off','toggle-device','secondary','cam')}</div>`,btn('Enter demo room '+icon('arrow'),'enter-room','',id))}
function room(id){const m=db.meetings.find(x=>x.id===id);if(!m)return;modal(m.title,`<div class="notice">Demo meeting room · Video, audio and screen sharing are simulated.</div><div class="call"><div class="participants"><div class="participant"><span class="avatar green">${initials(db.profile.name)}</span><small>${esc(db.profile.name)} · You</small></div><div class="participant"><span class="avatar yellow">SH</span><small>Sara Hassan · Cohost</small></div></div><div class="call-controls">${btn(icon('mic'),'toggle-device','secondary','mic')}${btn(icon('video'),'toggle-device','secondary','cam')}${btn(icon('chat')+'Chat','room-chat','secondary',id)}${btn('Leave','close','danger')}${btn('End session','end-session','',id)}</div></div>`, '',true)}
function csv(name,headers,rows){const safe=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};download(name,'\ufeff'+[headers,...rows].map(r=>r.map(safe).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function download(name,data,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function invoice(id){const i=db.invoices.find(x=>x.id===id);if(!i)return;modal('Invoice preview',`<div class="invoice">${brand()}<div class="invoice-head"><div><h2>INVOICE</h2><p>${esc(i.id)}<br>Issued ${niceDate(i.date)}</p></div>${badge(i.status)}</div><hr style="border:0;border-top:1px solid #dde4db"><div class="two-col"><div><p><b>From</b><br>Faster Meet<br>By Allam Solutions<br>info@allamsolutions.com</p></div><div><p><b>Bill to</b><br>${esc(db.profile.company)}<br>${esc(db.profile.name)}<br>${esc(db.profile.email)}</p></div></div><table><thead><tr><th>Description</th><th>Total EGP</th></tr></thead><tbody><tr><td>${esc(i.description)}</td><td>${money(i.amount)}</td></tr></tbody></table><div class="invoice-total">Total: EGP ${money(i.amount)}</div><p>Demonstration invoice · No payment was collected. Taxes and production billing rules are not calculated in this preview.</p></div>`,btn('Close','close','secondary')+btn(icon('download')+'Print / Save PDF','print'))}
function invite(id=''){const m=db.members.find(x=>x.id===id);formModal(m?'Manage teammate':'Invite someone great','member',`<input type="hidden" name="id" value="${esc(id)}">${inputField('Full name','name',m?.name||'','text',true,'maxlength="80"')}${inputField('Email','email',m?.email||'','email')}<div class="fields">${selectField('Role','role',['Member','Admin'],m?.role||'Member')}${selectField('Team','team',['Everyone','Design team','Engineering','Customer success'],m?.team||'Everyone')}</div><p>Invitations appear in the team list. No email is sent from the prototype.</p>`,m?'Save teammate':'Create demo invitation',m?btn('Remove','remove-member','danger',id):'')}
function customer(id=''){if(!isAdmin())return;const c=db.customers.find(x=>x.id===id);formModal(c?'Manage customer':'Add customer','customer',`<input type="hidden" name="id" value="${esc(id)}">${inputField('Workspace name','name',c?.name||'','text',true,'maxlength="80"')}${inputField('Email','email',c?.email||'','email')}<div class="fields">${selectField('Plan','plan',plans.map(p=>p.name),c?.plan||'Business')}${selectField('Account status','status',['Active','Pending','Suspended'],c?.status||'Active')}</div><p>Changes affect the sample customer directory and subscription reports.</p>`)}
function checkout(name){const p=plans.find(p=>p.name===name);if(!p)return;formModal('A little more possibility.','checkout',`<input type="hidden" name="plan" value="${p.name}"><div class="notice">Demo checkout · No real transaction or card details required.</div><div class="status-item"><b>${p.name} plan</b><span>EGP ${money(p.price)} / month</span></div>${inputField('Billing company','company',db.profile.company)}${selectField('Simulate payment result','result',['Successful payment','Failed payment'],'Successful payment')}<p>Confirmation updates your plan, adds a sample invoice, and appears in reports.</p>`,'Confirm demo payment')}
function integration(name){formModal(name+' connection','integration',`<input type="hidden" name="name" value="${esc(name)}"><div class="notice">This is a configuration preview. No API keys or passwords are required.</div>${selectField('Connection status','status',['Demo connected','Disconnected'],db.integrations[name]?'Demo connected':'Disconnected')}${name==='Amazon S3'?inputField('Archive bucket label','bucket','fastermeet-recordings-demo'):name==='Moodle'?inputField('Course workspace label','workspace','Horizon Learning'):name==='Zoom'?'<p>Multiple master accounts support meeting and webinar scheduling. Use the host table to add demo accounts and test overlapping meetings.</p>':'<p>Production authorization will be implemented during development.</p>'}`,'Save configuration')}
function reportExport(){const r=getReport(reportType);csv('FasterMeet-'+reportType+'.csv',r.headers,r.rows);toast('Report exported.')}
const actions={
'navigate':(_,id)=>go(id), 'close':()=>closeModal(), 'logout':()=>{session=null;sessionStorage.removeItem('fm-session');closeModal();render()},
'auth-mode':(_,id)=>{authMode=id;render()},'login-role':(_,id)=>{loginRole=id;render()},
'demo-login':()=>{session={role:loginRole};sessionStorage.setItem('fm-session',JSON.stringify(session));authMode='login';page='Overview';render();window.scrollTo(0,0);resumeInvite()},
'switch-role':()=>{session.role=isAdmin()?'customer':'admin';sessionStorage.setItem('fm-session',JSON.stringify(session));go('Overview');toast('Switched to '+session.role+' experience.')},
'mobile-menu':()=>{mobileOpen=!mobileOpen;$('.sidebar')?.classList.toggle('open',mobileOpen)},
'schedule':()=>schedule(),'schedule-day':(_,id)=>schedule(id),'edit-meeting':(_,id)=>schedule(today,id),'meeting-detail':(_,id)=>detail(id),'join':(_,id)=>join(id),'enter-room':(_,id)=>room(id),
'overview-tab':(el,id)=>{$$('.tabs button').forEach(b=>b.classList.toggle('active',b===el));$('#overview-meetings').innerHTML=(id==='Upcoming'?upcoming():db.meetings.filter(m=>m.status==='Completed')).slice(0,3).map(meetingRow).join('')||'<div class="empty">No meetings here yet.</div>'},
'meeting-filter':(_,id)=>{meetingFilter=id;render()},'clear-day':()=>{selectedDay=null;render()},
'month-prev':()=>{calMonth--;if(calMonth<0){calMonth=11;calYear--}render()},'month-next':()=>{calMonth++;if(calMonth>11){calMonth=0;calYear++}render()},'month-today':()=>{calMonth=now.getMonth();calYear=now.getFullYear();render()},
'day':(_,id)=>{page='Meetings';location.hash='Meetings';selectedDay=id;meetingFilter='All';render()},
'instant':()=>{const host=db.hosts.find(h=>hostAvailable(h.name,today,now.toTimeString().slice(0,5),30));if(!host){toast('All hosts are busy. Schedule a later time.');return}const m={id:uid('m'),title:'Instant meeting with '+db.profile.name,date:today,time:now.toTimeString().slice(0,5),duration:30,type:'Meeting',team:'Everyone',guests:'',host:host.name,status:'Scheduled',record:false};db.meetings.push(m);log('Instant meeting started');render();join(m.id)},
'join-link':()=>formModal('Join the conversation','join-link',inputField('Meeting link or ID','link','','text',true,'placeholder="Paste a demo invite link or meeting ID"')+'<p>Try a meeting from this demo workspace, for example <b>m1</b>.</p>','Continue'),
'cancel-meeting':(_,id)=>{const m=db.meetings.find(m=>m.id===id);if(m)modal('Cancel this meeting?',`<p>${esc(m.title)} will move to Cancelled. You can restore it from its details.</p>`,btn('Keep meeting','close','secondary')+btn('Cancel meeting','confirm-cancel','danger',id))},
'confirm-cancel':(_,id)=>{const m=db.meetings.find(m=>m.id===id);if(m){m.status='Cancelled';log('Meeting cancelled: '+m.title);closeModal();render();toast('Meeting cancelled.')}},
'share-meeting':(_,id)=>share('Share the invitation',linkFor(id)),
'share-recording':(_,id)=>share('Share the recording',location.href.split('#')[0]+'#recording/'+id),
'copy-link':async()=>{const field=$('#share-value');try{await navigator.clipboard.writeText(field.value);toast('Link copied.')}catch{field.focus();field.select();toast('Select and copy the link from the field.')}},
'ics':(_,id)=>{const m=db.meetings.find(m=>m.id===id);if(!m)return;const start=m.date.replaceAll('-','')+'T'+m.time.replace(':','')+'00';const d=new Date(m.date+'T'+m.time);d.setMinutes(d.getMinutes()+m.duration);const end=dateISO(d).replaceAll('-','')+'T'+d.toTimeString().slice(0,8).replaceAll(':','');const clean=s=>s.replaceAll('\\','\\\\').replaceAll(';','\\;').replaceAll(',','\\,').replaceAll('\n','\\n');download('FasterMeet-'+id+'.ics',['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Allam Solutions//Faster Meet Demo//EN','BEGIN:VEVENT','UID:'+id+'@fastermeet.demo','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+Z/,'Z'),'DTSTART;TZID='+db.profile.timezone+':'+start,'DTEND;TZID='+db.profile.timezone+':'+end,'SUMMARY:'+clean(m.title),'DESCRIPTION:Demo meeting. '+clean(linkFor(id)),'END:VEVENT','END:VCALENDAR'].join('\r\n'),'text/calendar');toast('Calendar file downloaded.')},
 'toggle-device':(el,id)=>{const on=el.dataset.on!=='true';el.dataset.on=on;el.innerHTML=icon(id==='mic'?'mic':'video')+(id==='mic'?'Microphone':'Camera')+(on?' on (demo)':' off');el.classList.toggle('lime',on)},
'room-chat':(_,id)=>formModal('Meeting chat','room-chat',`<input type="hidden" name="id" value="${esc(id)}"><div class="message"><span class="avatar yellow">SH</span><div><b>Sara Hassan</b><p>Hello! Ready when you are.</p></div></div><div id="room-messages"></div>${inputField('Your message','message','','text',true,'maxlength="1500"')}`,'Send message',btn('Back to room','enter-room','secondary',id)),
'end-session':(_,id)=>{const m=db.meetings.find(m=>m.id===id);if(m){m.status='Completed';if(m.record){db.recordings.unshift({id:uid('r'),title:m.title,date:today,duration:m.duration+':00',size:Math.round(m.duration*7),team:m.team,archive:'Cloud',retention:90});log('Recording ready: '+m.title)}log('Meeting completed: '+m.title);closeModal();render();toast('Session ended. '+(m.record?'Recording added to your library.':''))}},
'play':(_,id)=>{const r=db.recordings.find(r=>r.id===id);if(!r)return;modal(r.title,`<div class="notice">Sample playback preview · This is a generated demo clip, not a real meeting recording.</div><video id="demo-video" style="width:100%;border-radius:12px;background:#173d34;aspect-ratio:16/9" controls playsinline aria-label="Sample recording playback"></video><p>${niceDate(r.date)} · ${r.size} MB · ${esc(r.archive)} · Retained ${r.retention} days</p>`,btn('Download sample','download-recording','secondary',id));attachSampleVideo()},
'download-recording':async(_,id)=>{const r=db.recordings.find(r=>r.id===id);if(!r)return;toast('Preparing a short sample clip…');try{const blob=await sampleClip();download('FasterMeet-sample-'+r.id+'.webm',blob,'video/webm');toast('Sample clip downloaded.')}catch{download('FasterMeet-'+r.id+'-transcript.txt','FASTER MEET · DEMO TRANSCRIPT\n'+r.title+'\n\nAlex: Welcome, everyone. Let’s review the agenda.\nSara: The new workshop is ready to share.\nOmar: I will follow up with the team.\n\nThis is synthetic demonstration content.');toast('Sample transcript downloaded; video generation is unavailable in this browser.')}},
'archive-settings':()=>formModal('Recording archive & retention','archive',selectField('Default retention','retention',['30 days','60 days','90 days','365 days'],(db.recordings[0]?.retention||90)+' days')+selectField('Archive destination','destination',['Cloud','S3 archived'],db.integrations['Amazon S3']?'S3 archived':'Cloud')+'<p>Apply these settings to every demo recording. Real S3 archival is simulated.</p>','Apply to library'),
'channel':(_,id)=>{channel=id;render()},'invite':()=>invite(),'member-edit':(_,id)=>invite(id),
'remove-member':(_,id)=>{modal('Remove this teammate?',`<p>The sample member will be removed from this demo workspace.</p>`,btn('Keep member','close','secondary')+btn('Remove member','confirm-remove-member','danger',id))},
'confirm-remove-member':(_,id)=>{db.members=db.members.filter(m=>m.id!==id||m.role==='Owner');log('Team membership updated');closeModal();render();toast('Teammate removed.')},
'checkout':(_,id)=>checkout(id),'current-plan':()=>toast('You’re already on this plan.'),
'addon':(_,id)=>{if(db.addons.includes(id)){modal('Remove add-on?',`<p>Remove ${esc(id)} from the demo subscription?</p>`,btn('Keep','close','secondary')+btn('Remove','remove-addon','danger',id));return}formModal('Add more room','addon',`<input type="hidden" name="addon" value="${esc(id)}"><div class="notice">Demo purchase · No charge is made.</div><p>${esc(id)} · EGP ${id==='100 GB storage'?350:750} per month.</p>`,'Add to subscription')},
'remove-addon':(_,id)=>{db.addons=db.addons.filter(a=>a!==id);save();closeModal();render();toast('Add-on removed.')},
'renewal':()=>formModal('Subscription renewal','renewal',selectField('Renewal preference','renewal',['Auto-renew on','Auto-renew off'],db.renewal||'Auto-renew on')+'<p>Changes affect this sample subscription only.</p>'),
'invoice':(_,id)=>invoice(id),'print':()=>window.print(),'export-invoices':()=>{const r=getReport('Revenue');csv('FasterMeet-Invoices.csv',r.headers,r.rows);toast('Invoices exported.')},
'add-customer':()=>customer(),'customer-edit':(_,id)=>customer(id),'report-export':()=>reportExport(),
'plan-catalog':()=>modal('Plan catalog',`<p>Monthly demonstration prices, independent of the project development quotation.</p>${plans.map(p=>`<div class="status-item"><b>${p.name}</b><span>EGP ${money(p.price)} / month · ${p.capacity} people</span></div>`).join('')}`,btn('Close','close','secondary')),
'integration-config':(_,id)=>integration(id),
'webhook':()=>{const m=db.meetings.find(m=>m.status==='Scheduled');if(!m){toast('Schedule a meeting first to simulate a recording webhook.');return}db.recordings.unshift({id:uid('r'),title:m.title+' · webhook demo',date:today,duration:'05:00',size:35,team:m.team,archive:db.integrations['Amazon S3']?'S3 archived':'Cloud',retention:90});log('Simulated recording.completed webhook processed');render();toast('Webhook processed. A demo recording was added.')},
'add-host':()=>formModal('Add a demo Zoom account','host',inputField('Account label','name','','text',true,'maxlength="80"')+inputField('Demo host email','email','','email')+inputField('Participant capacity','capacity',300,'number',true,'min="2" max="10000"')+'<p>No Zoom login is required in the prototype.</p>','Add host'),
'map-course':()=>formModal('Link a learning session','moodle',inputField('Course name','course','','text',true,'maxlength="120"')+selectField('Meeting or webinar','session',db.meetings.filter(m=>m.status==='Scheduled').map(m=>m.title),'')+'<p>This maps a course to a scheduled event in the demo.</p>','Link session'),
'notifications':()=>{db.notificationsRead=true;save();modal('You’re in the loop.',db.activity.map(a=>`<div class="notification-item">${esc(a.text)}<small>${esc(a.time)}</small></div>`).join(''),btn('All caught up','close'))},
'help':()=>modal('A quick tour of Faster Meet',`<p>This interactive prototype is prepared by Allam Solutions for client review.</p><div class="status-item"><b>01 · Plan a conversation</b><span>Schedule, edit, share, join, end.</span></div><div class="status-item"><b>02 · Keep the ideas</b><span>Preview recordings and archive settings.</span></div><div class="status-item"><b>03 · Bring your team</b><span>Invite members and chat in channels.</span></div><div class="status-item"><b>04 · Grow your workspace</b><span>Try plans, demo checkout and invoices.</span></div><div class="status-item"><b>05 · See the whole picture</b><span>Switch to admin in Settings.</span></div><p>Data is stored in this browser. The payment, email, Zoom, S3, Vimeo, and Moodle experiences are simulated. All plan prices and activity figures are sample data. No real video, payments or emails are processed.</p>`,btn('Let’s explore','close')),
'reset-confirm':()=>modal('Start a fresh demo?',`<p>This replaces sample changes in this browser with the original demonstration workspace.</p>`,btn('Keep my changes','close','secondary')+btn('Reset demo','reset','danger')),
'reset':()=>{db=seed();save();closeModal();go('Overview');toast('Fresh workspace ready.')}
};
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){const fn=actions[el.dataset.action];if(fn)Promise.resolve(fn(el,el.dataset.id)).catch(err=>{console.error(err);toast('That action could not be completed. Please try again.')})}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();$('.sidebar')?.classList.remove('open');mobileOpen=false}if(e.key==='Tab'&&$('.modal')){const list=[...$('.modal').querySelectorAll('button,input,select,textarea,a')].filter(x=>!x.disabled&&x.type!=='hidden');if(list.length){if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0].focus()}}}});
document.addEventListener('change',e=>{if(e.target.id==='report-type'){reportType=e.target.value;render()}if(e.target.dataset.setting){db.profile[e.target.dataset.setting]=e.target.checked;save();toast('Preference saved.')}});
let searchTimer;document.addEventListener('input',e=>{if(['meeting-search','recording-search','customer-search'].includes(e.target.id)){const id=e.target.id,start=e.target.selectionStart;searchText=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{render();const field=$('#'+id);field?.focus();field?.setSelectionRange(start,start)},180)}});
document.addEventListener('keydown',e=>{if(e.target.id==='global-search'&&e.key==='Enter'){const value=e.target.value;page='Meetings';location.hash='Meetings';meetingFilter='All';searchText=value;render()}});
function hostAvailable(host,date,time,duration,exclude=''){const mins=t=>+t.split(':')[0]*60+(+t.split(':')[1]);return !db.meetings.some(m=>m.id!==exclude&&m.status==='Scheduled'&&m.host===host&&m.date===date&&mins(time)<mins(m.time)+m.duration&&mins(time)+duration>mins(m.time))}
const handlers={
auth:f=>{if(authMode==='reset'){modal('Recovery email preview',`<div class="notice">Preview only · No email has been sent.</div><h3>Reset your Faster Meet password</h3><p>We received a password reset request for ${esc(f.email)}. In the live application, a secure, expiring reset link will appear here.</p>`,btn('Back to sign in','auth-back'));actions['auth-back']=()=>{closeModal();authMode='login';render()};return}if(authMode==='register'){db.profile.name=f.name.trim();db.profile.email=f.email.trim();db.profile.type=f.type;db.profile.company=f.type==='Business'?f.name.split(' ')[0]+'’s workspace':'Personal workspace';save();session={role:'customer'};sessionStorage.setItem('fm-session',JSON.stringify(session));go('Overview');modal('Your workspace is ready.',`<p>A verification email would be sent to <b>${esc(f.email)}</b>. This preview lets you continue without sending email.</p>`,btn('Verify demo email & continue','close'));return}if(f.email.toLowerCase()!==(loginRole==='admin'?'admin@fastermeet.demo':'alex@example.com')||f.password!=='FasterMeet2026!'){$('#auth-error').textContent='Use the demo button below, or the demo credentials in README.md.';return}session={role:loginRole};sessionStorage.setItem('fm-session',JSON.stringify(session));go('Overview');resumeInvite()},
schedule:(f,form)=>{let host=f.host;const duration=Number(f.duration);if(duration<15||duration>480){$('#schedule-error').textContent='Choose a duration from 15 to 480 minutes.';return}if(f.date<today&&!f.id){$('#schedule-error').textContent='Choose today or a future date.';return}if(f.guests&&f.guests.split(',').some(x=>!/^\s*[^\s@]+@[^\s@]+\.[^\s@]+\s*$/.test(x))){$('#schedule-error').textContent='Enter valid guest emails separated by commas.';return}if(host==='Auto-allocate')host=db.hosts.find(h=>hostAvailable(h.name,f.date,f.time,duration,f.id))?.name;if(!host||!hostAvailable(host,f.date,f.time,duration,f.id)){$('#schedule-error').textContent='The selected host is busy. Choose another time or host.';return}const old=db.meetings.find(m=>m.id===f.id);const m={id:f.id||uid('m'),title:f.title.trim(),date:f.date,time:f.time,duration,type:f.type,team:f.team,guests:f.guests.trim(),host,status:'Scheduled',record:!!f.record};if(!m.title){$('#schedule-error').textContent='Add a meeting title.';return}if(old)Object.assign(old,m);else db.meetings.push(m);log((old?'Updated meeting: ':'Scheduled meeting: ')+m.title);closeModal();render();toast(old?'Meeting updated.':'Meeting scheduled. Your conversation is on the calendar.')},
'join-link':f=>{const id=f.link.split(/join\//).at(-1).split(/[?#&]/)[0].trim();join(id)},
chat:f=>{const text=f.message.trim();if(!text)return;db.messages.push({id:Date.now(),name:db.profile.name,channel,text,time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})});save();render();$('#messages').scrollTop=$('#messages').scrollHeight},
'room-chat':(f,form)=>{const row=document.createElement('div');row.className='message';row.innerHTML=`<span class="avatar green">${initials(db.profile.name)}</span><div><b>${esc(db.profile.name)}</b><p>${esc(f.message)}</p></div>`;$('#room-messages').appendChild(row);form.elements.message.value='';toast('Message added to the demo room.')},
member:f=>{const existing=db.members.find(m=>m.id===f.id);if(db.members.some(m=>m.email.toLowerCase()===f.email.toLowerCase()&&m.id!==f.id)){toast('This email is already on your team.');return}if(existing)Object.assign(existing,{name:f.name.trim(),email:f.email,role:f.role,team:f.team});else db.members.push({id:uid('u'),name:f.name.trim(),email:f.email,role:f.role,team:f.team,status:'Invited'});log(existing?'Teammate details updated':'Demo invitation created for '+f.name);closeModal();render();toast(existing?'Member updated.':'Invitation added. No email was sent.')},
customer:f=>{if(!isAdmin())return;const c=db.customers.find(c=>c.id===f.id);if(c)Object.assign(c,{name:f.name.trim(),email:f.email,plan:f.plan,status:f.status});else db.customers.push({id:uid('c'),name:f.name.trim(),email:f.email,plan:f.plan,status:f.status});log('Customer directory updated');closeModal();render();toast('Customer saved.')},
checkout:f=>{if(f.result==='Failed payment'){modal('Payment wasn’t completed.',`<p>Your current plan is unchanged. You can try the demo checkout again.</p>`,btn('Try again','checkout','',f.plan));return}const p=plans.find(p=>p.name===f.plan);db.plan=p.name;db.profile.company=f.company;const i={id:'FM-'+Date.now(),date:today,description:p.name+' plan · Monthly subscription',amount:p.price,status:'Paid'};db.invoices.unshift(i);const own=db.customers.find(c=>c.id==='c1');if(own)own.plan=p.name;log('Demo subscription changed to '+p.name);closeModal();render();modal('More room for great things.',`<div class="notice">Demo payment successful. No money was charged.</div><h3>Your ${p.name} plan is active.</h3><p>Your invoice is ready, and your workspace limits have been updated.</p>`,btn('View invoice','invoice','secondary',i.id)+btn('Keep exploring','close'))},
addon:f=>{if(!db.addons.includes(f.addon)){db.addons.push(f.addon);db.invoices.unshift({id:'FM-'+Date.now(),date:today,description:f.addon+' · Monthly add-on',amount:f.addon==='100 GB storage'?350:750,status:'Paid'});log('Demo add-on added: '+f.addon)}closeModal();render();toast('Add-on activated. No charge was made.')},
renewal:f=>{db.renewal=f.renewal;save();closeModal();toast('Demo renewal preference saved.')},
profile:f=>{Object.assign(db.profile,{name:f.name.trim(),email:f.email,company:f.company.trim(),type:f.type,timezone:f.timezone});const owner=db.members.find(m=>m.role==='Owner');if(owner){owner.name=db.profile.name;owner.email=f.email}log('Workspace profile updated');render();toast('Your workspace feels more like you.')},
integration:f=>{db.integrations[f.name]=f.status==='Demo connected';log(f.name+' demo connection updated');closeModal();render();toast('Demo configuration saved.')},
host:f=>{if(db.hosts.some(h=>h.name===f.name.trim())){toast('Use a unique host account label.');return}db.hosts.push({name:f.name.trim(),email:f.email,capacity:+f.capacity,status:'Available'});log('Demo Zoom master account added');closeModal();render();toast('Demo host added.')},
moodle:f=>{const m=db.meetings.find(m=>m.title===f.session);if(!m){toast('Schedule a meeting first.');return}db.moodle.push({course:f.course.trim(),session:f.session,date:m.date});log('Moodle course mapped: '+f.course);closeModal();render();toast('Course linked to the demo session.')},
archive:f=>{db.recordings.forEach(r=>{r.retention=parseInt(f.retention);r.archive=f.destination});log('Recording archive policy updated');closeModal();render();toast('Archive settings applied to the library.')}
};
document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const values=Object.fromEntries(new FormData(form));try{handlers[form.dataset.form]?.(values,form)}catch(err){console.error(err);toast('Unable to save. Please check the form and try again.')}});
let samplePromise;
function sampleClip(){if(samplePromise)return samplePromise;samplePromise=new Promise((resolve,reject)=>{try{if(!window.MediaRecorder)throw Error('No recording support');const c=document.createElement('canvas');c.width=960;c.height=540;const ctx=c.getContext('2d');const stream=c.captureStream(12);const recorder=new MediaRecorder(stream,{mimeType:MediaRecorder.isTypeSupported('video/webm;codecs=vp8')?'video/webm;codecs=vp8':'video/webm'}),chunks=[];recorder.ondataavailable=e=>chunks.push(e.data);recorder.onerror=reject;recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());resolve(new Blob(chunks,{type:'video/webm'}))};let frame=0;const draw=()=>{ctx.fillStyle='#163f3d';ctx.fillRect(0,0,960,540);ctx.strokeStyle='#ffffff12';for(let i=0;i<4;i++){ctx.beginPath();ctx.arc(760,160,100+i*60,0,Math.PI*2);ctx.stroke()}ctx.fillStyle='#d0f58b';ctx.font='bold 54px Arial';ctx.fillText('fastermeet.',65,110);ctx.fillStyle='white';ctx.font='bold 38px Arial';ctx.fillText('A conversation worth keeping.',65,240);ctx.fillStyle='#b3cabc';ctx.font='22px Arial';ctx.fillText('Interactive demo · Sample recording',65,295);ctx.fillText('Allam Solutions',65,465);ctx.fillStyle='#d0f58b';ctx.fillRect(65,350,Math.min(650,frame/36*650),4);frame++};draw();recorder.start();const interval=setInterval(draw,1000/12);setTimeout(()=>{clearInterval(interval);recorder.stop()},3000)}catch(err){samplePromise=null;reject(err)}});return samplePromise}
async function attachSampleVideo(){try{const blob=await sampleClip();const video=$('#demo-video');if(video){video.src=URL.createObjectURL(blob);video.onloadeddata=()=>video.play().catch(()=>{})}}catch{const video=$('#demo-video');if(video)video.outerHTML='<div class="empty">Sample video generation is unavailable in this browser. The demo transcript is available from Download sample.</div>'}}
function resumeInvite(){const hash=decodeURIComponent(location.hash).match(/^#(join|recording)\//)?decodeURIComponent(location.hash):initialInvite;if(hash.startsWith('#join/'))join(hash.slice(6));if(hash.startsWith('#recording/'))actions.play(null,hash.slice(11))}
// Icon-only controls always have accessible labels.
const observer=new MutationObserver(()=>{$$('button').filter(b=>!b.textContent.trim()&&!b.getAttribute('aria-label')).forEach(b=>{const labels={'meeting-detail':'Meeting details','share-recording':'Share recording','download-recording':'Download sample recording',play:'Play sample recording',notifications:'Notifications',close:'Close dialog','mobile-menu':'Open navigation','toggle-device':'Toggle device preview'};b.setAttribute('aria-label',labels[b.dataset.action]||b.dataset.action||'Action')})});observer.observe(document.body,{childList:true,subtree:true});
save();render();if(session)resumeInvite();
